import os
for bm in ['spatial', 'object']:
    for name in ['obs_features.pt', 'k_samples.pt', 'expert_actions.pt']:
        p = f'/root/autodl-tmp/crm_cache_pi05/{bm}/{name}'
        if os.path.exists(p):
            import torch
            d = torch.load(p, map_location='cpu', weights_only=False)
            if hasattr(d, 'shape'):
                print(f'{bm}/{name}: shape={d.shape}, size={os.path.getsize(p)/1e6:.1f}MB')
            elif isinstance(d, dict):
                print(f'{bm}/{name}: keys={list(d.keys())[:5]}, size={os.path.getsize(p)/1e6:.1f}MB')
            elif isinstance(d, list):
                print(f'{bm}/{name}: len={len(d)}, size={os.path.getsize(p)/1e6:.1f}MB')
            else:
                print(f'{bm}/{name}: type={type(d).__name__}, size={os.path.getsize(p)/1e6:.1f}MB')
"
